type Money struct { minor int64; cur string }

func (m Money) Add(n Money) Money {           // new value, same type
	if m.cur != n.cur { panic("currency mismatch") }
	return Money{minor: m.minor + n.minor, cur: m.cur}
}

func (m Money) Scale(f int64) Money { return Money{minor: m.minor * f, cur: m.cur} }
func Zero(cur string) Money         { return Money{cur: cur} }   // identity element
